import type { BackupOptions, BackupSnapshot, BackupRunResult } from "./types";
import { Alert, Badge, Button, Group, Loader, Stack, Table, Text } from "@mantine/core";
import { useWidgetAction, useWidgetClock, useWidgetHost, useWidgetOptions, useWidgetQuery, useWidgetServices } from "@homarr/widget-sdk";
export default function Backups() {
  const host = useWidgetHost();
  const services = useWidgetServices();
  const options = useWidgetOptions<BackupOptions>();
  const now = useWidgetClock(60000);
  const query = useWidgetQuery<BackupSnapshot>("files", {}, {refetchInterval:60000});
  const run = useWidgetAction<BackupRunResult,Record<string,never>>("runBackup");
  const files = query.data?.files ?? [];
  const latest = files[0];
  const status = query.data?.status;
  const finishedAt = status?.finishedAt ?? latest?.modifiedAt;
  const overdue = finishedAt && now !== null && now - finishedAt > options.maximumAgeHours * 3600000;
  let label = "No backup report";
  let color = "gray";
  if (finishedAt) { label = "Recent backup activity"; color = "teal"; }
  if (status?.status === "success") label = "Backup succeeded";
  if (overdue) { label = "Backup overdue"; color = "orange"; }
  if (status?.status === "failure") { label = "Backup failed"; color = "red"; }
  if (query.data?.running || run.isPending || status?.status === "running") { label = "Backup running"; color = "blue"; }
  const execute = async () => {
    if (await services.confirm({title:"Run backup now?",message:"Run the owner-configured backup executable on the Homarr server?"})) run.mutate({});
  };
  return <Stack p="md" h="100%" gap="sm" style={{overflow:"auto"}}>
    <Group justify="space-between"><Text fw={600}>{options.title}</Text><Badge color={color}>{label}</Badge></Group>
    {query.isPending && <Loader size="sm" />}
    {query.error && <Alert color="red">{query.error.message}</Alert>}
    {(query.data?.errors ?? []).map((error,index) => <Alert key={index} color="yellow">{error}</Alert>)}
    {status?.message && <Text size="sm">{status.message}</Text>}
    {finishedAt && <Text size="sm">{new Date(finishedAt).toLocaleString(host.locale)}</Text>}
    {latest && <Text size="xs" c="dimmed">{latest.name} · {(latest.bytes/1048576).toFixed(1)} MiB</Text>}
    {status?.durationSeconds != null && <Text size="xs">Last duration: {status.durationSeconds}s</Text>}
    <Group><Button size="xs" variant="light" onClick={() => void query.refetch()}>Refresh</Button>
      {host.displayMode === "compact" && <Button size="xs" variant="subtle" onClick={services.openAdvanced}>History and files</Button>}
      {query.data?.commandConfigured && <Button size="xs" disabled={host.isEditMode || query.data.running} loading={run.isPending} onClick={() => void execute()}>Run backup</Button>}
    </Group>
    {run.error && <Alert color="red">{run.error.message}</Alert>}
    {run.data?.completed && <Text size="xs" c="teal">Command completed in {run.data.durationSeconds}s. Refresh to read its status report.</Text>}
    {host.displayMode === "advanced" && <>
      <Text fw={600}>Run history</Text>
      {!(query.data?.history?.length) && <Text c="dimmed" size="sm">Add history entries to the configured JSON status report.</Text>}
      <Table><Table.Thead><Table.Tr><Table.Th>Finished</Table.Th><Table.Th>Status</Table.Th><Table.Th>Duration</Table.Th></Table.Tr></Table.Thead><Table.Tbody>{(query.data?.history ?? []).map((entry,index) => <Table.Tr key={index}><Table.Td>{entry.finishedAt ? new Date(entry.finishedAt).toLocaleString(host.locale) : "Unknown"}</Table.Td><Table.Td>{entry.status}</Table.Td><Table.Td>{entry.durationSeconds ?? "—"}s</Table.Td></Table.Tr>)}</Table.Tbody></Table>
      <Text fw={600}>Backup files</Text>
      <Table><Table.Thead><Table.Tr><Table.Th>File</Table.Th><Table.Th>Modified</Table.Th><Table.Th>MiB</Table.Th></Table.Tr></Table.Thead><Table.Tbody>{files.map((file) => <Table.Tr key={file.name}><Table.Td>{file.name}</Table.Td><Table.Td>{new Date(file.modifiedAt).toLocaleString(host.locale)}</Table.Td><Table.Td>{(file.bytes/1048576).toFixed(1)}</Table.Td></Table.Tr>)}</Table.Tbody></Table>
    </>}
    <Text size="xs" c="dimmed">Activity reports do not verify restore integrity. Test restores separately.</Text>
  </Stack>;
}

