import type { BackupOptions, BackupFile, BackupRecord } from "./types";
import { readdir, readFile, stat } from "node:fs/promises";
import { join, isAbsolute } from "node:path";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { defineWidgetServer, getWidgetServerContext } from "@homarr/widget-sdk/server";
import { backupCommand } from "./command";
const execute = promisify(execFile);
let running = false;
const timestamp = (value:unknown):number|null => { let next=NaN; if(typeof value==="number") next=value; else if(typeof value==="string") next=Date.parse(value); return Number.isFinite(next) ? next : null; };
const record = (input:unknown):BackupRecord => {
  const value = input && typeof input === "object" ? input as Record<string,unknown> : {};
  const status = value.status;
  return {
    status: status === "success" || status === "failure" || status === "running" ? status : "unknown",
    finishedAt: timestamp(value.finishedAt),
    durationSeconds: typeof value.durationSeconds === "number" ? value.durationSeconds : null,
    bytes: typeof value.bytes === "number" ? value.bytes : null,
    message: typeof value.message === "string" ? value.message.slice(0,500) : "",
  };
};
export default defineWidgetServer({
  files: async (_input, context) => {
    const { options } = await getWidgetServerContext<BackupOptions>(context);
    const errors = [];
    const files:BackupFile[] = [];
    let status:BackupRecord|null = null;
    let history:BackupRecord[] = [];
    try {
      if (typeof options.directory !== "string" || !isAbsolute(options.directory)) throw new Error("Choose an absolute backup directory inside Homarr");
      const entries = await readdir(options.directory, {withFileTypes:true});
      const matches = entries.filter((entry) => entry.isFile() && (!options.suffix || entry.name.endsWith(options.suffix)));
      if (matches.length > 1000) errors.push("The directory has over 1,000 matching files; narrow the suffix to inspect the full set.");
      for (const entry of matches.slice(0, 1000)) {
        context.signal.throwIfAborted();
        const info = await stat(join(options.directory, entry.name));
        files.push({name:entry.name, bytes:info.size, modifiedAt:info.mtimeMs});
      }
      files.sort((a,b) => b.modifiedAt - a.modifiedAt);
    } catch (error) { errors.push(error instanceof Error ? error.message : String(error)); }
    if (options.statusFile) {
      try {
        if (typeof options.statusFile !== "string" || !isAbsolute(options.statusFile)) throw new Error("Status file must use an absolute container path");
        if ((await stat(options.statusFile)).size > 1048576) throw new Error("Status report exceeds 1 MiB");
        const report:unknown = JSON.parse(await readFile(options.statusFile, "utf8"));
        status = record(report);
        if (report && typeof report === "object" && "history" in report && Array.isArray(report.history)) history = report.history.slice(-100).map(record).sort((a,b) => (b.finishedAt ?? 0) - (a.finishedAt ?? 0));
      } catch (error) { errors.push(error instanceof Error ? error.message : String(error)); }
    }
    return {files:files.slice(0,100),status,history,errors,running,commandConfigured:Boolean(backupCommand.executable)};
  },
  runBackup: async (_input, context) => {
    const {isPreview} = await getWidgetServerContext(context);
    if (isPreview) return {simulated:true};
    if (!backupCommand.executable || !isAbsolute(backupCommand.executable)) throw new Error("Configure an absolute executable in command.ts and activate the package first");
    if (running) throw new Error("A backup command is already running");
    running = true;
    const started = Date.now();
    try {
      await execute(backupCommand.executable, backupCommand.args, {shell:false,timeout:backupCommand.timeoutMs,maxBuffer:524288,signal:context.signal});
      return {completed:true,durationSeconds:Math.round((Date.now()-started)/1000)};
    } catch (error) {
      const code = error && typeof error === "object" && "code" in error ? error.code : "unknown";
      throw new Error(`The configured backup command failed (${code}). Check the backup service logs.`);
    } finally { running = false; }
  },
});

