// Owner configuration: edit this source file deliberately, then preview and activate.
// The dashboard cannot supply executable paths or arguments. No shell is used.
export const backupCommand = {
  executable: "", // Example: "/usr/local/bin/run-backup"
  args: [] as string[],
  timeoutMs: 240000,
};

