export type BackupOptions = {title:string;directory:string;suffix:string;maximumAgeHours:number;statusFile:string};
export interface BackupRecord {status:"success"|"failure"|"running"|"unknown";finishedAt:number|null;durationSeconds:number|null;bytes:number|null;message:string;}
export interface BackupFile {name:string;bytes:number;modifiedAt:number;}
export interface BackupSnapshot {files:BackupFile[];status:BackupRecord|null;history:BackupRecord[];errors:string[];running:boolean;commandConfigured:boolean;}
export interface BackupRunResult {simulated?:boolean;completed?:boolean;durationSeconds?:number;}
